"""Compile .protos to *_pb2.py without protobuf's runtime-version pin.

Run by `zig build pb2`: gen_pb2.py (<x.proto> <x_pb2.py>)... Needs grpcio-tools.
"""

import os
import re
import sys
import tempfile

from grpc_tools import protoc


def gen(src, dst):
    inc, name = os.path.split(os.path.abspath(src))
    stem = name.removesuffix(".proto")
    with tempfile.TemporaryDirectory() as tmp:
        if protoc.main(["protoc", f"-I{inc}", f"--python_out={tmp}", os.path.join(inc, name)]) != 0:
            sys.exit(f"protoc failed on {src}")
        with open(os.path.join(tmp, f"{stem}_pb2.py")) as f:
            s = f.read()
    s = s.replace("from google.protobuf import runtime_version as _runtime_version\n", "")
    s = re.sub(r"_runtime_version.ValidateProtobufRuntimeVersion\(.*?\)\n", "", s, flags=re.S)
    s = s.replace("# NO CHECKED-IN PROTOBUF GENCODE\n", "")
    s = re.sub(r"# Protobuf Python Version: .*\n", "", s)
    # REUSE-IgnoreStart
    s = s.replace("# Generated by the protocol buffer compiler.  DO NOT EDIT!\n",
                  "# SPDX-FileCopyrightText: 2019 Google LLC, Andrew Hines\n"
                  "# SPDX-License-Identifier: Apache-2.0\n"
                  f"# Generated by protoc from src/cpp/proto/{stem}.proto (google/visqol), with the\n"
                  "# runtime-version pin removed so any protobuf>=3.20 can load it.\n"
                  "# Regenerate with `zig build pb2`.  DO NOT EDIT!\n")
    # REUSE-IgnoreEnd
    with open(dst, "w") as f:
        f.write(s)


args = sys.argv[1:]
for src, dst in zip(args[::2], args[1::2]):
    gen(src, dst)
